    body += at(2, 'pop', `<rect x="490" y="96" width="${CELL}" height="${CELL}" fill="white" stroke="${C.muted}" stroke-width="2.5"/>` + text(505, 152, '10 km', { size: 18 }) + text(528, 117, '10 km', { size: 18, anchor: 'start' }), 0.5);
    body += at(2, 'pop', text(505, 76, '한 칸', { size: 20, color: C.muted }), 0.3);
