    body += ch.body;
    body += at(3, 'pop', tag(BX[1], f(ch.y(26) - 22), '약 26 ℃', HOT, { size: 18 }), 0.2) + glowRect(BX[1] - 26, f(ch.y(26) - 4), 52, f(Y0 - ch.y(26) + 4), 3, C.red, 0.4, 6);
    body += at(3, 'pop', tag(BX[3], f(ch.y(2) - 22), '약 2 ℃', COLD, { size: 18 }), 0.7) + glowRect(BX[3] - 26, f(ch.y(2) - 4), 52, f(Y0 - ch.y(2) + 4), 3, C.blue, 0.9, 6);
