    const censer = (x) => `<path d="M${x - 8} ${IY + 26} V${IY + 32} H${x - 24} L${x - 28} ${IY + 40} H${x + 28} L${x + 24} ${IY + 32} H${x + 8} V${IY + 26}" fill="${C.mint}" stroke="${C.green}" stroke-width="2.5" stroke-linejoin="round"/><path d="M${x - 32} ${IY} H${x + 32} Q${x + 28} ${IY + 28} ${x} ${IY + 28} Q${x - 28} ${IY + 28} ${x - 32} ${IY} Z" fill="${C.mint}" stroke="${C.green}" stroke-width="2.5" stroke-linejoin="round"/><path d="M${x - 16} ${IY + 4} Q${x - 10} ${IY + 20} ${x} ${IY + 24} Q${x + 10} ${IY + 20} ${x + 16} ${IY + 4}" stroke="${C.green}" stroke-width="2" fill="none"/><circle cx="${x}" cy="${IY - 18}" r="19" fill="${C.mint}" stroke="${C.green}" stroke-width="2.5"/><circle cx="${x}" cy="${IY - 18}" r="5" fill="white" stroke="${C.green}" stroke-width="1.5"/>` + [0, 1, 2, 3, 4, 5].map((k) => { const a = (k * Math.PI) / 3; return `<circle cx="${f(x + 11 * Math.cos(a))}" cy="${f(IY - 18 + 11 * Math.sin(a))}" r="4" fill="white" stroke="${C.green}" stroke-width="1.5"/>`; }).join('') + `<circle cx="${x}" cy="${IY - 41}" r="4" fill="${C.green}"/>`;
    const icehouse = (x) => `<path d="M${x - 64} ${IY + 32} Q${x} ${IY - 58} ${x + 64} ${IY + 32} Z" fill="${C.mint}" stroke="${C.green}" stroke-width="2.5"/><rect x="${x - 24}" y="${IY - 30}" width="12" height="16" fill="${C.line}" stroke="${C.muted}" stroke-width="2.5"/><rect x="${x + 12}" y="${IY - 30}" width="12" height="16" fill="${C.line}" stroke="${C.muted}" stroke-width="2.5"/><path d="M${x - 28} ${IY - 30} H${x - 8} M${x + 8} ${IY - 30} H${x + 28}" stroke="${C.muted}" stroke-width="3.5" stroke-linecap="round"/><path d="M${x - 16} ${IY + 32} V${IY + 12} Q${x} ${IY - 4} ${x + 16} ${IY + 12} V${IY + 32}" fill="${C.ink}" stroke="${C.muted}" stroke-width="3"/>`;
    const haenyeo = (x) => `<path d="M${x - 64} ${IY + 6} Q${x - 48} ${IY - 4} ${x - 32} ${IY + 6} T${x} ${IY + 6} T${x + 32} ${IY + 6} T${x + 64} ${IY + 6} V${IY + 34} H${x - 64} Z" fill="${C.sky}" stroke="${C.blue}" stroke-width="2.5"/><circle cx="${x + 26}" cy="${IY - 2}" r="13" fill="${C.orange}" stroke="${C.ink}" stroke-width="2"/><circle cx="${x - 20}" cy="${IY - 8}" r="13" fill="${C.ink}"/><rect x="${x - 30}" y="${IY - 14}" width="20" height="9" rx="4" fill="${C.sky}" stroke="white" stroke-width="2"/><path d="M${x - 8} ${IY - 2} L${x + 14} ${IY - 4}" stroke="${C.ink}" stroke-width="4" stroke-linecap="round"/>`;
    const ITEMS = [[jongmyo, '종묘', '역사적', 2, OLD], [censer, '청자 향로', '예술적', 2, HOT], [icehouse, '석빙고', '과학적', 3, COLD], [haenyeo, '해녀 문화', '생태적', 3, OK]];
    let body = at(1, 'pop', tag(320, 44, '국가유산', PLAIN, { size: 22 }), 0.1);
    body += ITEMS.map(([draw, name], i) => at(1, 'pop', draw(X[i]) + text(X[i], 222, name, { size: 18 }), f(0.3 + i * 0.3))).join('');
    body += ITEMS.map(([, , val, n, col], i) => shown(n, g(`drop drop${n}`, `<path d="M${X[i]} 230 V246" stroke="${col[1]}" stroke-width="3"/>` + tag(X[i], 266, val, col, { size: 20 }), f(0.2 + (i % 2) * 0.6))) + ring(X[i], IY, 46, n, col[1], f(0.4 + (i % 2) * 0.6))).join('');
    body += shown(4, `<path class="draw draw4" pathLength="1" d="M40 290 Q40 302 54 302 H306 Q320 302 320 312 Q320 302 334 302 H586 Q600 302 600 290" stroke="${C.green}" stroke-width="3" fill="none"/>`);
